    notes: ["What a result means: a pathogenic BRCA1/2 variant makes PARP inhibitors an option, raises the case for risk-reducing surgery or surveillance, and means blood relatives can be tested."],
    targets: ["brca", "parp"], drugs: ["olaparib", "talazoparib"], cancers: ["ovarian", "breast-hr-positive", "tnbc", "pancreatic", "prostate"], companies: ["myriad-genetics"], trials: ["solo-1"],
