const terms: TermInput[] = [
  term({
    related: ["laboratory-certification-test-authorization","research-use-only","companion-diagnostic-term","analytical-vs-clinical-validation"], asOf: "2026-11-08", id: "fda-ldt-rule", wikipedia: W("Laboratory-developed_test"), name: "FDA laboratory-developed test (LDT) rule", category: "Regulation",
    tldr: "A laboratory-developed test is described by its development and use within a laboratory. Laboratory oversight, product authorization and evidence supporting a particular test use are separate questions.",
    summary: "FDA issued its laboratory-developed-test rule in May 2024. Its current notice states that a federal court vacated that rule in March 2025 and that FDA restored the earlier regulatory text in September 2025. The vacated phaseout schedule should not be presented as a current requirement. An LDT description alone does not establish FDA authorization, research-only status or clinical usefulness. Check the actual laboratory, product and intended use rather than assigning every LDT one approval or evidence status.",
    technologies: ["companion-diagnostic", "mrd-testing", "mced"], terms: ["ivdr", "regulatory-agencies"], drugs: ["galleri", "signatera", "cancerguard"],
    links: [{"label":"FDA: current laboratory-developed-test rule notice","url":"https://www.fda.gov/medical-devices/in-vitro-diagnostics/laboratory-developed-tests"},{"label":"CMS: Clinical Laboratory Improvement Amendments","url":"https://www.cms.gov/medicare/quality/clinical-laboratory-improvement-amendments"},{"label":"CMS: CLIA analytical oversight and clinical validity (2013 FAQ; historical FDA discussion not used)","url":"https://www.cms.gov/regulations-and-guidance/legislation/clia/downloads/ldt-and-clia_faqs.pdf"}] }),
  term({ id: "ivdr", wikipedia: W("In_Vitro_Diagnostic_Medical_Devices_Regulation"), name: "IVDR (EU In Vitro Diagnostic Regulation 2017/746)", category: "Regulation",
    tldr: "Europe's rules for diagnostic tests, which since 2022 require most cancer tests to be certified by an independent body before they carry a CE mark, with deadlines for older tests running to 2029.",
    summary: "Regulation (EU) 2017/746 replaced the 1998 IVD Directive and applied from 26 May 2022, moving from self-declaration to risk-based classification (A to D) in which about 80% of tests, including companion diagnostics (class C) and the bulk of cancer assays, need notified-body assessment. Companion diagnostics also require consultation with the medicines regulator. Because notified-body capacity lagged, Regulation (EU) 2024/1860 extended transition for legacy devices to 31 December 2027 (class D), 31 December 2028 (class C) and 31 December 2029 (class B and A sterile), provided manufacturers had applied to a notified body by set dates, and required manufacturers to warn of supply interruptions. In-house tests made by hospital laboratories have a separate, lighter regime under Article 5(5). The UK operates its own UKCA regime with continued recognition of CE marks. For patients the CE mark under IVDR is closer to FDA approval than the old CE mark was, but still does not require proof of clinical utility.",
    technologies: ["companion-diagnostic"], terms: ["fda-ldt-rule", "regulatory-agencies"],
    links: [{ label: "Regulation (EU) 2024/1860 (EUR-Lex)", url: "https://eur-lex.europa.eu/eli/reg/2024/1860/oj/eng" }, { label: "European Commission: in vitro diagnostic medical devices", url: "https://health.ec.europa.eu/medical-devices-sector/new-regulations_en" }] }),
  term({ id: "sensitivity-specificity", name: "Sensitivity and specificity", category: "Diagnostics", wikipedia: W("Sensitivity_and_specificity"),
    tldr: "Sensitivity is the share of people with the disease a test catches; specificity is the share of healthy people it correctly clears. No test scores 100% on both, and for screening the trade-off decides how many false alarms you get.",
    summary: "Sensitivity (true-positive rate) and specificity (true-negative rate) are properties of the test at a chosen cut-off and are usually estimated against a reference standard such as colonoscopy or biopsy in a study like ECLIPSE or BLUE-C. What a person experiences, the chance that a positive result is real, is the positive predictive value, which depends on how common the disease is: at a 1% cancer prevalence, a test with 99% specificity still generates about as many false positives as true positives. Screening tests trade sensitivity against specificity by moving the cut-off; a multi-cancer blood test set to high specificity (99.5% for Galleri) accepts low sensitivity for early-stage cancer. Sensitivity for precancerous lesions, not cancer, is what distinguishes tests that prevent colorectal cancer from tests that detect it.",
    terms: ["ppv", "screening", "overdiagnosis"], trials: ["blue-c", "eclipse-shield"],
    links: [{ label: "Wikipedia", url: W("Sensitivity_and_specificity") }] }),
  term({ id: "overdiagnosis", name: "Overdiagnosis", category: "Screening", wikipedia: W("Overdiagnosis"),
    tldr: "Finding a cancer that would never have caused symptoms or death in a person's lifetime, so that the diagnosis and treatment bring harm without benefit. It is the main downside of screening.",
    summary: "Overdiagnosis is invisible to the individual: a screen-detected cancer is treated and the person is cured of a disease that would not have hurt them. It is measured at population level as the excess incidence in a screened group that is never matched by a deficit later. Estimates are around 10-20% of screen-detected breast cancers in most reviews (the UK Independent Breast Screening Review put it at about 19%), a large share of PSA-detected low-grade prostate cancers before MRI-first pathways, and much of the rise in thyroid cancer and thin melanoma incidence. Remedies include raising thresholds (MRI-first prostate screening, Lung-RADS), renaming indolent lesions, and active surveillance rather than treatment. Multi-cancer blood tests raise the same question for cancers with no screening today.",
    terms: ["screening", "stage-shift", "sensitivity-specificity", "psa"], technologies: ["prostate-screening-psa-mri", "mammography", "active-surveillance", "skin-cancer-screening"],
    links: [{ label: "Independent UK Panel on Breast Cancer Screening (Lancet 2012)", url: "https://doi.org/10.1016/S0140-6736(12)61611-0" }] }),
];

